// tests/wasm/wasm_test.mjs: the wasm32 build of vbm-sse against the Lean reference (run by scripts/test_wasm.sh; test code, not shipped).
// Usage: node wasm_test.mjs VBM.wasm VECTORS.jsonl     (rows of vbm-sse-vectors-1, generated by the Lean REFERENCE)
// Checks: the module imports nothing; every row on every cut (whole, one byte per chunk, each two-way split): the events, the last event ID and the reconnection time equal the row's; the allocator refuses an impossible size;
// an oversized chunk is ARG; no leak (the live bytes are unchanged and memory does not grow over many streams). Exit 0 = all pass.
import { readFileSync } from "node:fs";
import { load, OK, ARG } from "./vbm_sse.mjs";

const [wasmPath, vecPath] = process.argv.slice(2);
if (!vecPath) { console.error("usage: wasm_test.mjs VBM.wasm VECTORS.jsonl"); process.exit(2); }
const wasm = readFileSync(wasmPath);
const imports = WebAssembly.Module.imports(new WebAssembly.Module(wasm));
let failures = 0;
const fail = (m) => { console.error("FAIL: " + m); failures++; };
if (imports.length) fail("the module has imports: " + imports.map((i) => i.module + "." + i.name).join(" "));
const lib = await load(wasm);
const hex = (s) => Uint8Array.from(s.match(/../g) ?? [], (h) => parseInt(h, 16));
const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);

/** Run the chunks through a fresh reader: the events collected, the last report's last event ID and retry. */
function run(chunks) {
  const r = lib.reader(); const events = []; let last = null;
  try { for (const c of chunks) { const res = r.feed(c); if (res.code !== OK) throw new Error("feed returned " + res.code); events.push(...res.report.events); last = res.report; } }
  finally { r.free(); }
  return { events, lastEventId: last.lastEventId, retry: last.retry };
}
function same(row, got) {
  if (got.events.length !== row.events.length) return "the number of events";
  for (let i = 0; i < row.events.length; i++) {
    const e = row.events[i], g = got.events[i];
    if (!eq(g.type, hex(e.type)) || !eq(g.data, hex(e.data)) || !eq(g.lastEventId, hex(e.last_event_id))) return `event ${i}`;
  }
  if (!eq(got.lastEventId, hex(row.last_event_id))) return "the last event ID";
  const want = row.retry === null ? null : BigInt(row.retry);
  if (got.retry !== want) return `the reconnection time (want ${want}, got ${got.retry})`;
  return null;
}

// the reconnection time as a string: JSON numbers above 2^53 lose bits
const quoteRetry = (line) => line.replace(/"retry":(\d+)\}$/, '"retry":"$1"}');
const lines = readFileSync(vecPath, "utf8").split("\n").filter(Boolean);
let runs = 0;
for (let id = 0; id < lines.length; id++) {
  const text = quoteRetry(lines[id]), row = JSON.parse(text), input = hex(row.input);
  const cuts = [[input], ...Array.from({ length: input.length + 1 }, (_, k) => [input.subarray(0, k), input.subarray(k)])];
  if (input.length) cuts.push(Array.from(input, (b) => Uint8Array.of(b)));
  for (const cs of cuts) {
    let got; try { got = run(cs); } catch (e) { fail(`row ${id}: the module failed (${e.message}): a trap is never an answer`); break; }
    const why = same(row, got); runs++;
    if (why) { fail(`row ${id} (${cs.length} chunk(s)): ${why} differs from the reference`); break; }
  }
}
if (lines.length < Number(process.env.VBM_MIN_ROWS || 1000)) fail(`only ${lines.length} rows`);
console.log(`wasm_test: ${lines.length} rows, ${runs} cuts agree with the reference`);

// arguments and the allocator hook
if (lib.exports.vbm_sse_wasm_alloc(1500000000) !== 0) fail("an impossible allocation was not refused");
{ const r = lib.reader(); if (r.feed({ length: 0x7fffffff }).code !== ARG) fail("an oversized chunk is not ARG"); r.free(); }
console.log("wasm_test: the allocator refuses an impossible size; an oversized chunk is ARG");

// leak: the arena returns to its live baseline after every stream, and does not grow over many streams
const doc = new TextEncoder().encode("retry: 7\nid: 9\nevent: e\ndata: x\ndata: y\n\n: c\r\ndata");
const once = () => { const r = lib.reader(); r.feed(doc); r.feed(doc.subarray(0, 5)); r.free(); };
once(); once(); const live0 = lib.live(); let mem0 = 0;
const iters = 5000;
for (let i = 0; i < iters; i++) {
  if (i === 500) mem0 = lib.memoryBytes();
  once();
  if (process.env.VBM_SSE_TEST_LEAK && i % 2) lib.exports.vbm_sse_wasm_alloc(64);   // a deliberate leak: this check must then FAIL
}
const live1 = lib.live(), growth = lib.memoryBytes() - mem0;
if (live1 !== live0 || growth > 65536) fail(`leak: ${live1 - live0} live bytes, ${growth} bytes of memory growth over ${iters} streams`);
else console.log(`wasm_test: no leak: live bytes unchanged (${live0}), ${growth} bytes of growth over ${iters} streams`);

if (failures) { console.error(`wasm_test: ${failures} failure(s)`); process.exit(1); }
console.log("wasm_test: ok");
